      throw new Error('Dynamic code execution is not allowed.')\n\
    },\n\
  })\n\
  // eslint-disable-next-line no-extend-native\n\
  Object.defineProperty(Function.prototype, 'constructor', {\n\
    value: proxyFunctionConstructor,\n\
    writable: false,\n\
    configurable: false,\n\
    enumerable: false,\n\
  })\n\
  globalThis.Function = proxyFunctionConstructor\n\
  // globalThis.Function = function() {\n\
  //   throw new Error('Function is not available')\n\
  // }\n\
\n\
  const excludes = [\n\
    Function.prototype.toString,\n\
    Function.prototype.toLocaleString,\n\
    Object.prototype.toString,\n\
  ]\n\
  const freezeObjectProperty = (obj, freezedObj = new Set()) => {\n\
    if (obj == null) return\n\
    switch (typeof obj) {\n\
      case 'object':\n\
      case 'function':\n\
        if (freezedObj.has(obj)) return\n\
        // Object.freeze(obj)\n\
        freezedObj.add(obj)\n\
        for (const [name, { ...config }] of Object.entries(Object.getOwnPropertyDescriptors(obj))) {\n\
          if (!excludes.includes(config.value)) {\n\
            if (config.writable) config.writable = false\n\
            if (config.configurable) config.configurable = false\n\
            Object.defineProperty(obj, name, config)\n\
          }\n\
          freezeObjectProperty(config.value, freezedObj)\n\
        }\n\
    }\n\
  }\n\
  freezeObjectProperty(globalThis)\n\
\n\
  console.log('Preload finished.')\n\
}\n\
"
}
